631	16	\N	1	1	report_delivery_document	\N	stock.report_delivery_document	qweb	stock/report/report_deliveryslip.xml	primary	{"en_US": "<t t-name=\\"stock.report_delivery_document\\">\\n        <t t-call=\\"web.html_container\\">\\n            <t t-call=\\"web.external_layout\\">\\n                <t t-set=\\"o\\" t-value=\\"o.with_context(lang=o._get_report_lang())\\"/>\\n                <t t-set=\\"partner\\" t-value=\\"o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False\\"/>\\n\\n                <t t-set=\\"address\\">\\n                    <div name=\\"div_outgoing_address\\">\\n                        <div name=\\"outgoing_delivery_address\\" t-if=\\"o.should_print_delivery_address()\\">\\n                            <strong>Delivery Address</strong>\\n                            <div t-out=\\"o.move_ids[0].partner_id or o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                        </div>\\n                        <div name=\\"outgoing_warehouse_address\\" t-elif=\\"o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id\\">\\n                            <strong>Warehouse Address</strong>\\n                            <div t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                        </div>\\n                    </div>\\n                </t>\\n                <t t-set=\\"information_block\\">\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-7\\" name=\\"div_incoming_address\\">\\n                            <t t-set=\\"show_partner\\" t-value=\\"False\\"/>\\n                            <div name=\\"vendor_address\\" t-if=\\"o.picking_type_id.code=='incoming' and partner\\">\\n                                <strong>Vendor Address</strong>\\n                                <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                            </div>\\n                            <div name=\\"customer_address\\" t-if=\\"o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id\\">\\n                                <strong>Customer</strong>\\n                                <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                            </div>\\n                            <div t-if=\\"show_partner\\" name=\\"partner_header\\">\\n                                <div t-field=\\"partner.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </t>\\n                <div class=\\"page\\">\\n                    <h2 style=\\"margin-top: 15px;\\">\\n                        <span t-out=\\"o.picking_type_id._get_code_report_name()\\"/>\\n                        <span t-field=\\"o.name\\">WH/OUT/0001</span>\\n                    </h2>\\n                    <div class=\\"oe_structure\\"/>\\n                    <div id=\\"informations\\" class=\\"report-wrapping-flexbox clearfix row mb-4\\">\\n                        <div t-if=\\"o.origin\\" class=\\"col col-3 mw-100 mb-2\\" name=\\"div_origin\\">\\n                            <strong>Order</strong>\\n                            <div t-field=\\"o.origin\\" class=\\"m-0\\">S0001</div>\\n                        </div>\\n                        <div t-if=\\"o.picking_type_id.code == 'internal' and o.partner_id\\" class=\\"col col-3 mw-100 mb-2\\" name=\\"div_contact\\">\\n                            <strong>Contact</strong>\\n                            <div t-field=\\"o.partner_id\\" class=\\"m-0\\"/>\\n                        </div>\\n                        <div t-if=\\"o.state\\" class=\\"col col-3 mw-100 mb-2\\" name=\\"div_sched_date\\">\\n                            <strong>Shipping Date</strong>\\n                            <div t-if=\\"o.state == 'done'\\" t-field=\\"o.date_done\\" class=\\"m-0\\"/>\\n                            <div t-else=\\"\\" t-field=\\"o.scheduled_date\\" class=\\"m-0\\"/>\\n                        </div>\\n                        <div t-if=\\"o.user_id\\" class=\\"col-auto\\" name=\\"div_operator\\">\\n                            <strong>Operator:</strong>\\n                                <p t-field=\\"o.user_id\\">Mitchel Admin</p>\\n                        </div>\\n                    </div>\\n                    <div class=\\"oe_structure\\"/>\\n                    <t t-set=\\"format_number\\" t-value=\\"lambda x: int(x) if x == int(x) else x\\"/>\\n                    <table class=\\"table table-sm table-borderless\\" t-if=\\"o.state!='done'\\" name=\\"stock_move_table\\">\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sm_product\\"><strong>Product</strong></th>\\n                                <th name=\\"th_sm_ordered\\" class=\\"text-end\\"><strong>Ordered</strong></th>\\n                                <th name=\\"th_sm_quantity\\" class=\\"text-end\\"><strong>Delivered</strong></th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                            <t t-set=\\"lines\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty)\\"/>\\n                            <tr t-foreach=\\"lines\\" t-as=\\"move\\">\\n                                <td>\\n                                    <span t-field=\\"move.product_id\\">Customizable Desk</span>\\n                                    <p t-if=\\"move.description_picking and move.description_picking != move.product_id.name and move._get_report_description_picking()\\">\\n                                        <span t-out=\\"move._get_report_description_picking()\\" t-options=\\"{'widget': 'text'}\\">Description on transfer</span>\\n                                    </p>\\n                                </td>\\n                                <td class=\\"o_td_quantity text-end\\">\\n                                    <span t-out=\\"format_number(move.product_uom_qty)\\" class=\\"text-nowrap\\">3.00</span>\\n                                    <span t-field=\\"move.product_uom\\" groups=\\"uom.group_uom\\">units</span>\\n                                    <t t-if=\\"move.packaging_uom_id != move.product_uom\\" groups=\\"uom.group_uom\\">\\n                                        <br/>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_qty\\">1.00</span>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_id\\">Pack of 6</span>\\n                                    </t>\\n                                </td>\\n                                <td class=\\"o_td_quantity text-end\\">\\n                                    <span t-out=\\"format_number(move.quantity)\\" class=\\"text-nowrap\\">3.00</span>\\n                                    <span t-field=\\"move.product_uom\\" groups=\\"uom.group_uom\\">units</span>\\n                                    <t t-if=\\"move.packaging_uom_id != move.product_uom\\" groups=\\"uom.group_uom\\">\\n                                        <br/>\\n                                        <span class=\\"text-muted\\" t-esc=\\"move.product_uom._compute_quantity(move.quantity, move.packaging_uom_id)\\">1.00</span>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_id\\">Pack of 6</span>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                        </tbody>\\n                    </table>\\n                    <table class=\\"table table-sm table-borderless\\" t-elif=\\"o.move_line_ids and o.state=='done'\\" name=\\"stock_move_line_table\\">\\n                        <t t-set=\\"has_multi_level_packages\\" t-value=\\"len(o.package_history_ids.filtered(lambda ph: ph.parent_dest_id)) &gt; 0\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"False\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"o.move_line_ids.mapped('lot_id')\\" groups=\\"stock.group_lot_on_delivery_slip\\"/>\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sml_product\\">Product</th>\\n                                <th name=\\"th_sml_package\\" t-if=\\"has_multi_level_packages\\">Package</th>\\n                                <th name=\\"th_sml_qty_ordered\\" class=\\"text-end\\" t-if=\\"not has_serial_number\\">\\n                                    Ordered\\n                                </th>\\n                                <th name=\\"lot_serial\\" class=\\"text-end\\" t-else=\\"\\">\\n                                    Lot/Serial Number\\n                                </th>\\n                                <th name=\\"th_sml_quantity\\" class=\\"text-end\\">Delivered</th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\\n                                    product + description + uom combinations\\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\\n                            <!-- If has destination packages => create sections of corresponding products -->\\n                            <t t-if=\\"o.packages_count\\" name=\\"has_packages\\">\\n                                <t t-set=\\"packages\\" t-value=\\"o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id).package_id\\"/>\\n                                <t t-foreach=\\"packages\\" t-as=\\"package\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_package_section_line\\"/>\\n                                    <t t-set=\\"package_move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: l.result_package_id == package or l.package_history_id.outermost_dest_id == package).sorted('product_id')\\"/>\\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"package_move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\\n                                    <t t-else=\\"\\">\\n                                        <t t-set=\\"aggregated_lines\\" t-value=\\"package_move_lines._get_aggregated_product_quantities(strict=True)\\"/>\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                                <!-- Make sure we do another section for package-less products if they exist -->\\n                                <t t-set=\\"move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: not l.result_package_id)\\"/>\\n                                <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_ids.move_line_ids._get_aggregated_product_quantities(except_package=True)\\"/>\\n                                <t t-if=\\"move_lines or aggregated_lines\\" name=\\"no_package_move_lines\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_no_package_section_line\\" name=\\"no_package_section\\"/>\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-elif=\\"aggregated_lines\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                            </t>\\n                            <!-- No destination packages -->\\n                            <t t-else=\\"\\">\\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                <t t-if=\\"has_serial_number\\">\\n                                    <tr t-foreach=\\"o.move_ids.move_line_ids\\" t-as=\\"move_line\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                    </tr>\\n                                </t>\\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\\n                                <t t-else=\\"\\" name=\\"aggregated_move_lines\\">\\n                                    <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_ids.move_line_ids._get_aggregated_product_quantities()\\"/>\\n                                    <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                    <div class=\\"oe_structure\\"/>\\n                    <t t-set=\\"backorders\\" t-value=\\"o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))\\"/>\\n                    <div t-if=\\"not (o.backorder_ids and backorders)\\" class=\\"oe_structure\\"/>\\n                    <div t-else=\\"\\">\\n                        <p class=\\"mt-5\\">\\n                            <span>Remaining quantities not yet delivered:</span>\\n                        </p>\\n                        <table class=\\"table table-sm table-borderless\\" name=\\"stock_backorder_table\\">\\n                            <thead>\\n                                <tr>\\n                                    <th name=\\"th_sb_product\\"><strong>Product</strong></th>\\n                                    <th/>\\n                                    <th name=\\"th_sb_quantity\\" class=\\"text-end\\"><strong>Quantity</strong></th>\\n                                </tr>\\n                            </thead>\\n                            <tbody>\\n                                <tr t-foreach=\\"backorders.mapped('move_ids').filtered(lambda x: x.product_uom_qty)\\" t-as=\\"bo_line\\">\\n                                    <td class=\\"w-auto\\">\\n                                        <span t-field=\\"bo_line.product_id\\">Office Chair</span>\\n                                        <p t-if=\\"bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line._get_report_description_picking()\\">\\n                                            <span t-out=\\"bo_line._get_report_description_picking()\\" t-options=\\"{'widget': 'text'}\\">Description on transfer</span>\\n                                        </p>\\n                                    </td>\\n                                    <td/>\\n                                    <td class=\\"text-end w-auto\\">\\n                                        <span t-out=\\"format_number(bo_line.product_uom_qty)\\">3.00</span>\\n                                        <span t-field=\\"bo_line.product_uom\\" groups=\\"uom.group_uom\\">units</span>\\n                                    </td>\\n                                </tr>\\n                            </tbody>\\n                        </table>\\n                    </div>\\n\\n                    <div t-if=\\"not o.signature\\" class=\\"oe_structure\\"/>\\n                    <div t-else=\\"\\" class=\\"mt32 ml64 mr4\\" name=\\"signature\\">\\n                        <div class=\\"offset-8\\">\\n                            <strong>Signature</strong>\\n                        </div>\\n                        <div class=\\"offset-8\\">\\n                            <img t-att-src=\\"image_data_uri(o.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                        </div>\\n                        <div t-if=\\"o.partner_id.name\\" class=\\"offset-8 text-center\\">\\n                            <p t-field=\\"o.partner_id.name\\">John Doe</p>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n         </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_delivery_document">\n        <t t-call="web.html_container">\n            <t t-call="web.external_layout">\n                <t t-set="o" t-value="o.with_context(lang=o._get_report_lang())"/>\n                <t t-set="partner" t-value="o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False"/>\n\n                <t t-set="address">\n                    <div name="div_outgoing_address">\n                        <div name="outgoing_delivery_address" t-if="o.should_print_delivery_address()">\n                            <strong>Delivery Address</strong>\n                            <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                        <div name="outgoing_warehouse_address" t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                            <strong>Warehouse Address</strong>\n                            <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                    </div>\n                </t>\n                <t t-set="information_block">\n                    <div class="row">\n                        <div class="col-7" name="div_incoming_address">\n                            <t t-set="show_partner" t-value="False"/>\n                            <div name="vendor_address" t-if="o.picking_type_id.code=='incoming' and partner">\n                                <strong>Vendor Address</strong>\n                                <t t-set="show_partner" t-value="True"/>\n                            </div>\n                            <div name="customer_address" t-if="o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id">\n                                <strong>Customer</strong>\n                                <t t-set="show_partner" t-value="True"/>\n                            </div>\n                            <div t-if="show_partner" name="partner_header">\n                                <div t-field="partner.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n                <div class="page">\n                    <h2 style="margin-top: 15px;">\n                        <span t-out="o.picking_type_id._get_code_report_name()"/>\n                        <span t-field="o.name">WH/OUT/0001</span>\n                    </h2>\n                    <div class="oe_structure"/>\n                    <div id="informations" class="report-wrapping-flexbox clearfix row mb-4">\n                        <div t-if="o.origin" class="col col-3 mw-100 mb-2" name="div_origin">\n                            <strong>Order</strong>\n                            <div t-field="o.origin" class="m-0">S0001</div>\n                        </div>\n                        <div t-if="o.picking_type_id.code == 'internal' and o.partner_id" class="col col-3 mw-100 mb-2" name="div_contact">\n                            <strong>Contact</strong>\n                            <div t-field="o.partner_id" class="m-0"/>\n                        </div>\n                        <div t-if="o.state" class="col col-3 mw-100 mb-2" name="div_sched_date">\n                            <strong>Shipping Date</strong>\n                            <div t-if="o.state == 'done'" t-field="o.date_done" class="m-0"/>\n                            <div t-else="" t-field="o.scheduled_date" class="m-0"/>\n                        </div>\n                        <div t-if="o.user_id" class="col-auto" name="div_operator">\n                            <strong>Operator:</strong>\n                                <p t-field="o.user_id">Mitchel Admin</p>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                    <t t-set="format_number" t-value="lambda x: int(x) if x == int(x) else x"/>\n                    <table class="table table-sm table-borderless" t-if="o.state!='done'" name="stock_move_table">\n                        <thead>\n                            <tr>\n                                <th name="th_sm_product"><strong>Product</strong></th>\n                                <th name="th_sm_ordered" class="text-end"><strong>Ordered</strong></th>\n                                <th name="th_sm_quantity" class="text-end"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-set="lines" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty)"/>\n                            <tr t-foreach="lines" t-as="move">\n                                <td>\n                                    <span t-field="move.product_id">Customizable Desk</span>\n                                    <p t-if="move.description_picking and move.description_picking != move.product_id.name and move._get_report_description_picking()">\n                                        <span t-out="move._get_report_description_picking()" t-options="{'widget': 'text'}">Description on transfer</span>\n                                    </p>\n                                </td>\n                                <td class="o_td_quantity text-end">\n                                    <span t-out="format_number(move.product_uom_qty)" class="text-nowrap">3.00</span>\n                                    <span t-field="move.product_uom" groups="uom.group_uom">units</span>\n                                    <t t-if="move.packaging_uom_id != move.product_uom" groups="uom.group_uom">\n                                        <br/>\n                                        <span class="text-muted" t-field="move.packaging_uom_qty">1.00</span>\n                                        <span class="text-muted" t-field="move.packaging_uom_id">Pack of 6</span>\n                                    </t>\n                                </td>\n                                <td class="o_td_quantity text-end">\n                                    <span t-out="format_number(move.quantity)" class="text-nowrap">3.00</span>\n                                    <span t-field="move.product_uom" groups="uom.group_uom">units</span>\n                                    <t t-if="move.packaging_uom_id != move.product_uom" groups="uom.group_uom">\n                                        <br/>\n                                        <span class="text-muted" t-esc="move.product_uom._compute_quantity(move.quantity, move.packaging_uom_id)">1.00</span>\n                                        <span class="text-muted" t-field="move.packaging_uom_id">Pack of 6</span>\n                                    </t>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <table class="table table-sm table-borderless" t-elif="o.move_line_ids and o.state=='done'" name="stock_move_line_table">\n                        <t t-set="has_multi_level_packages" t-value="len(o.package_history_ids.filtered(lambda ph: ph.parent_dest_id)) &gt; 0"/>\n                        <t t-set="has_serial_number" t-value="False"/>\n                        <t t-set="has_serial_number" t-value="o.move_line_ids.mapped('lot_id')" groups="stock.group_lot_on_delivery_slip"/>\n                        <thead>\n                            <tr>\n                                <th name="th_sml_product">Product</th>\n                                <th name="th_sml_package" t-if="has_multi_level_packages">Package</th>\n                                <th name="th_sml_qty_ordered" class="text-end" t-if="not has_serial_number">\n                                    Ordered\n                                </th>\n                                <th name="lot_serial" class="text-end" t-else="">\n                                    Lot/Serial Number\n                                </th>\n                                <th name="th_sml_quantity" class="text-end">Delivered</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\n                                    product + description + uom combinations\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\n                            <!-- If has destination packages => create sections of corresponding products -->\n                            <t t-if="o.packages_count" name="has_packages">\n                                <t t-set="packages" t-value="o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id).package_id"/>\n                                <t t-foreach="packages" t-as="package">\n                                    <t t-call="stock.stock_report_delivery_package_section_line"/>\n                                    <t t-set="package_move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: l.result_package_id == package or l.package_history_id.outermost_dest_id == package).sorted('product_id')"/>\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="package_move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\n                                    <t t-else="">\n                                        <t t-set="aggregated_lines" t-value="package_move_lines._get_aggregated_product_quantities(strict=True)"/>\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                                <!-- Make sure we do another section for package-less products if they exist -->\n                                <t t-set="move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: not l.result_package_id)"/>\n                                <t t-set="aggregated_lines" t-value="o.move_ids.move_line_ids._get_aggregated_product_quantities(except_package=True)"/>\n                                <t t-if="move_lines or aggregated_lines" name="no_package_move_lines">\n                                    <t t-call="stock.stock_report_delivery_no_package_section_line" name="no_package_section"/>\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <t t-elif="aggregated_lines">\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                            </t>\n                            <!-- No destination packages -->\n                            <t t-else="">\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\n                                <t t-if="has_serial_number">\n                                    <tr t-foreach="o.move_ids.move_line_ids" t-as="move_line">\n                                        <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                    </tr>\n                                </t>\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\n                                <t t-else="" name="aggregated_move_lines">\n                                    <t t-set="aggregated_lines" t-value="o.move_ids.move_line_ids._get_aggregated_product_quantities()"/>\n                                    <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                    <div class="oe_structure"/>\n                    <t t-set="backorders" t-value="o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))"/>\n                    <div t-if="not (o.backorder_ids and backorders)" class="oe_structure"/>\n                    <div t-else="">\n                        <p class="mt-5">\n                            <span>Remaining quantities not yet delivered:</span>\n                        </p>\n                        <table class="table table-sm table-borderless" name="stock_backorder_table">\n                            <thead>\n                                <tr>\n                                    <th name="th_sb_product"><strong>Product</strong></th>\n                                    <th/>\n                                    <th name="th_sb_quantity" class="text-end"><strong>Quantity</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr t-foreach="backorders.mapped('move_ids').filtered(lambda x: x.product_uom_qty)" t-as="bo_line">\n                                    <td class="w-auto">\n                                        <span t-field="bo_line.product_id">Office Chair</span>\n                                        <p t-if="bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line._get_report_description_picking()">\n                                            <span t-out="bo_line._get_report_description_picking()" t-options="{'widget': 'text'}">Description on transfer</span>\n                                        </p>\n                                    </td>\n                                    <td/>\n                                    <td class="text-end w-auto">\n                                        <span t-out="format_number(bo_line.product_uom_qty)">3.00</span>\n                                        <span t-field="bo_line.product_uom" groups="uom.group_uom">units</span>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n\n                    <div t-if="not o.signature" class="oe_structure"/>\n                    <div t-else="" class="mt32 ml64 mr4" name="signature">\n                        <div class="offset-8">\n                            <strong>Signature</strong>\n                        </div>\n                        <div class="offset-8">\n                            <img t-att-src="image_data_uri(o.signature)" style="max-height: 4cm; max-width: 8cm;"/>\n                        </div>\n                        <div t-if="o.partner_id.name" class="offset-8 text-center">\n                            <p t-field="o.partner_id.name">John Doe</p>\n                        </div>\n                    </div>\n                </div>\n            </t>\n         </t>\n    </t>\n\n    	f	t	2026-06-04 07:57:55.375189	2026-06-04 07:57:55.375189	f
220	16	\N	1	1	view_speedscope_index	\N	web.view_speedscope_index	qweb	web/views/speedscope_template.xml	primary	{"en_US": "<t t-name=\\"web.view_speedscope_index\\">\\n        &lt;!DOCTYPE html&gt;\\n        <html lang=\\"en\\">\\n            <head>\\n                <meta charset=\\"UTF-8\\"/>\\n                <title>Speedscope for odoo</title>\\n                <script>window.location.hash=\\"#localProfilePath=1\\"</script>\\n                <link href=\\"https://fonts.googleapis.com/css?family=Source+Code+Pro\\" rel=\\"stylesheet\\"/>\\n                <link rel=\\"stylesheet\\" t-attf-href=\\"{{cdn}}reset.8c46b7a1.css\\" crossorigin=\\"anonymous\\" integrity=\\"sha256-mrA/937EwtEDE+8XZ/62tNz2T/BnCLth8QmWsWKpvD8=\\"/>\\n            </head>\\n            <body>\\n                <script t-attf-src=\\"{{cdn}}speedscope.026f36b0.js\\" crossorigin=\\"anonymous\\" integrity=\\"sha256-CvDqAOMjq0Sv/D59O5JSbzzXoClZ3rptt6ts8D/6CWw=\\"/>\\n                <script>\\n                const b64 = '<t t-esc=\\"speedscope_base64\\"/>';\\n                document.addEventListener(\\"DOMContentLoaded\\", () =&gt; {\\n                    speedscope.loadFileFromBase64('Profile', b64);\\n                });\\n                </script>\\n            </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.view_speedscope_index">\n        &lt;!DOCTYPE html&gt;\n        <html lang="en">\n            <head>\n                <meta charset="UTF-8"/>\n                <title>Speedscope for odoo</title>\n                <script>window.location.hash="#localProfilePath=1"</script>\n                <link href="https://fonts.googleapis.com/css?family=Source+Code+Pro" rel="stylesheet"/>\n                <link rel="stylesheet" t-attf-href="{{cdn}}reset.8c46b7a1.css" crossorigin="anonymous" integrity="sha256-mrA/937EwtEDE+8XZ/62tNz2T/BnCLth8QmWsWKpvD8="/>\n            </head>\n            <body>\n                <script t-attf-src="{{cdn}}speedscope.026f36b0.js" crossorigin="anonymous" integrity="sha256-CvDqAOMjq0Sv/D59O5JSbzzXoClZ3rptt6ts8D/6CWw="/>\n                <script>\n                const b64 = '<t t-esc="speedscope_base64"/>';\n                document.addEventListener("DOMContentLoaded", () =&gt; {\n                    speedscope.loadFileFromBase64('Profile', b64);\n                });\n                </script>\n            </body>\n        </html>\n    </t>\n	f	t	2026-06-04 07:33:07.475652	2026-06-04 07:33:07.475652	\N
221	16	\N	1	1	view_memory	\N	web.view_memory	qweb	web/views/memory_template.xml	primary	{"en_US": "<t t-name=\\"web.view_memory\\">\\n        &lt;!DOCTYPE html&gt;\\n        <html lang=\\"en\\">\\n        <head>\\n            <meta charset=\\"UTF-8\\"/>\\n            <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\"/>\\n            <title>Memory Usage Visualization</title>\\n            <script src=\\"https://cdn.jsdelivr.net/npm/chart.js\\"/>\\n            <script src=\\"https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels\\"/>\\n            <style>\\n                /* General body and layout styles */\\n                body {\\n                    font-family: Arial, sans-serif;\\n                    margin: 20px;\\n                    background-color: #f9f9f9;\\n                }\\n                .container {\\n                    display: flex;\\n                    flex-direction: column;\\n                    gap: 20px;\\n                }\\n\\n                /* Row definitions for the new layout */\\n                .top-row {\\n                    height: 40vh; /* Line graph takes 40% of the viewport height */\\n                }\\n                .bottom-row {\\n                    display: flex;\\n                    gap: 20px;\\n                    /* The height of this row will be determined by its content */\\n                }\\n\\n                /* Chart container styles */\\n                .chart-container {\\n                    position: relative;\\n                    background: #fff;\\n                    border: 1px solid #ddd;\\n                    border-radius: 5px;\\n                    padding: 15px;\\n                    height: 100%;\\n                    width: 100%;\\n                }\\n                \\n                /* Specific styling for the bottom row elements */\\n                .bar-chart-wrapper {\\n                    flex: 2; /* Bar chart takes 2/3 of the width */\\n                    min-height: 400px; /* Minimum height for the bar chart */\\n                }\\n                .traceback-panel {\\n                    flex: 1; /* Traceback panel takes 1/3 of the width */\\n                    background: #f5f5f5;\\n                    border: 1px solid #ddd;\\n                    border-radius: 5px;\\n                    padding: 15px;\\n                    overflow-y: auto;\\n                    min-height: 400px; /* Match min-height for alignment */\\n                    height: fit-content; /* Adjust height to content */\\n                }\\n\\n                /* Traceback panel content styling */\\n                .traceback-header {\\n                    font-weight: bold;\\n                    margin-bottom: 10px;\\n                    color: #333;\\n                }\\n                .traceback-item {\\n                    background: white;\\n                    margin: 5px 0;\\n                    padding: 8px;\\n                    border-radius: 3px;\\n                    border-left: 3px solid #007acc;\\n                    font-family: monospace;\\n                    font-size: 12px;\\n                }\\n                .traceback-file {\\n                    color: #007acc;\\n                    font-weight: bold;\\n                }\\n                .copyable {\\n                    cursor: pointer;\\n                    user-select: all;\\n                    padding: 2px 4px;\\n                    border-radius: 3px;\\n                    transition: background-color 0.2s;\\n                }\\n                .copyable:hover {\\n                    background-color: #e8f4f8;\\n                }\\n                .traceback-line {\\n                    color: #666;\\n                }\\n                .no-selection {\\n                    color: #999;\\n                    font-style: italic;\\n                    text-align: center;\\n                    padding-top: 50px;\\n                }\\n            </style>\\n        </head>\\n        <body>\\n            <div class=\\"container\\">\\n                <!-- Top row for the full-width line chart -->\\n                <div class=\\"top-row\\">\\n                    <div class=\\"chart-container\\">\\n                        <canvas id=\\"totalMemoryChart\\"/>\\n                    </div>\\n                </div>\\n                <!-- Bottom row for the bar chart and traceback panel -->\\n                <div class=\\"bottom-row\\">\\n                    <div class=\\"bar-chart-wrapper chart-container\\" id=\\"memoryChartContainer\\">\\n                        <canvas id=\\"memoryChart\\"/>\\n                    </div>\\n                    <div class=\\"traceback-panel\\" id=\\"tracebackPanel\\">\\n                        <div class=\\"no-selection\\">Click a point on the top chart, then a bar below to see details.</div>\\n                    </div>\\n                </div>\\n            </div>\\n\\n            <script>\\n                // Get data from Odoo template\\n                const rawData = JSON.parse(atob('<t t-esc=\\"memory_graph\\"/>'));\\n\\n                // --- UTILITY FUNCTIONS ---\\n                function formatBytes(bytes) {\\n                    if (bytes === 0) return '0 B';\\n                    const k = 1024;\\n                    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\\n                    const i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));\\n                    const value = bytes / Math.pow(k, i);\\n                    return `${value.toFixed(1)} ${sizes[i]}`;\\n                }\\n\\n                function formatTimestamp(timestamp) {\\n                    const date = new Date(timestamp * 1000);\\n                    return date.toLocaleString();\\n                }\\n\\n                function getLastFileFromTraceback(traceback) {\\n                    if (!traceback || traceback.length === 0) return \\"unknown:0\\";\\n                    const lastFrame = traceback[traceback.length - 1];\\n                    return `${lastFrame[0]}:${lastFrame[1]}`;\\n                }\\n                \\n                function getFullTracebackKey(traceback) {\\n                    if (!traceback || traceback.length === 0) return \\"unknown\\";\\n                    return traceback.map(frame =&gt; `${frame[0]}:${frame[1]}`).join(' -&gt; ');\\n                }\\n\\n                // --- DYNAMIC UI UPDATES ---\\n                function updateChartHeight(chart, dataLength) {\\n                    const container = document.getElementById('memoryChartContainer');\\n                    if (dataLength === 0) {\\n                        container.style.height = '400px'; // Reset to min-height\\n                        chart.resize();\\n                        return;\\n                    }\\n                    \\n                    const minBarHeight = 35; // Minimum height per bar for readability\\n                    const padding = 100; // Extra space for axes and labels\\n                    const newHeight = Math.max(400, (dataLength * minBarHeight) + padding);\\n                    \\n                    container.style.height = newHeight + 'px';\\n                    chart.resize();\\n                }\\n\\n                function showTraceback(traceback, size, fullTracebackKey) {\\n                    const panel = document.getElementById('tracebackPanel');\\n                    if (!traceback || traceback.length === 0) {\\n                        panel.innerHTML = '<div class=\\"no-selection\\">No traceback available</div>';\\n                        return;\\n                    }\\n\\n                    let html = `<div class=\\"traceback-header\\">Traceback (${formatBytes(size)})</div>`;\\n\\n                    if (fullTracebackKey) {\\n                        html += `\\n                            <div style=\\"margin-bottom: 10px; padding: 8px; background: #e8f4f8; border-radius: 3px; font-size: 11px; color: #555;\\">\\n                                <strong>Full Path:</strong> <span class=\\"copyable\\" title=\\"Click to select for copying\\">${fullTracebackKey}</span>\\n                            </div>\\n                        `;\\n                    }\\n\\n                    traceback.forEach(frame =&gt; {\\n                        const [filename, lineNo, functionName, code] = frame;\\n                        html += `\\n                            <div class=\\"traceback-item\\">\\n                                <div class=\\"traceback-file copyable\\" title=\\"Click to select for copying\\">${filename}:${lineNo}</div>\\n                                <div>in <strong>${functionName || 'unknown'}</strong></div>\\n                                ${code ? `<div class=\\"traceback-line\\">${code}</div>` : ''}\\n                            </div>\\n                        `;\\n                    });\\n\\n                    panel.innerHTML = html;\\n                }\\n\\n                // --- CHART LOGIC ---\\n                const totalSizes = rawData.map(entry =&gt;\\n                    entry.samples.reduce((sum, sample) =&gt; sum + sample.size, 0)\\n                );\\n                const lineLabels = rawData.map(entry =&gt; formatTimestamp(entry.start));\\n\\n                let selectedIndexes = [];\\n                let currentBreakdownData = [];\\n\\n                const updateBarChart = () =&gt; {\\n                    if (selectedIndexes.length === 1) {\\n                        const entry = rawData[selectedIndexes[0]];\\n                        const groupedData = {};\\n                        entry.samples.forEach(sample =&gt; {\\n                            const key = getLastFileFromTraceback(sample.traceback);\\n                            if (!groupedData[key]) {\\n                                groupedData[key] = { size: 0, traceback: sample.traceback, samples: [] };\\n                            }\\n                            groupedData[key].size += sample.size;\\n                            groupedData[key].samples.push(sample);\\n                        });\\n\\n                        currentBreakdownData = Object.entries(groupedData).map(([key, data]) =&gt; ({\\n                            label: key,\\n                            size: data.size,\\n                            traceback: data.traceback,\\n                            samples: data.samples\\n                        })).sort((a, b) =&gt; b.size - a.size);\\n\\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\\n                        breakdownChart.data.datasets = [{\\n                            label: `Memory Usage`,\\n                            data: currentBreakdownData.map(item =&gt; item.size),\\n                            backgroundColor: 'rgba(54, 162, 235, 0.6)',\\n                            borderColor: 'rgba(54, 162, 235, 1)',\\n                            borderWidth: 1\\n                        }];\\n                        breakdownChart.options.plugins.title.text = `Memory Breakdown for ${formatTimestamp(entry.start)}`;\\n\\n                    } else if (selectedIndexes.length === 2) {\\n                        const [idx1, idx2] = selectedIndexes.sort((a, b) =&gt; a - b);\\n                        const entry1 = rawData[idx1];\\n                        const entry2 = rawData[idx2];\\n\\n                        const groupDataByFullTraceback = (entry) =&gt; {\\n                            const grouped = {};\\n                            entry.samples.forEach(sample =&gt; {\\n                                const key = getFullTracebackKey(sample.traceback);\\n                                if (!grouped[key]) {\\n                                    grouped[key] = { size: 0, traceback: sample.traceback, lastFile: getLastFileFromTraceback(sample.traceback) };\\n                                }\\n                                grouped[key].size += sample.size;\\n                            });\\n                            return grouped;\\n                        };\\n\\n                        const data1 = groupDataByFullTraceback(entry1);\\n                        const data2 = groupDataByFullTraceback(entry2);\\n                        const labelSet = new Set([...Object.keys(data1), ...Object.keys(data2)]);\\n                        \\n                        let diffData = [];\\n                        labelSet.forEach(fullTracebackKey =&gt; {\\n                            const size1 = data1[fullTracebackKey]?.size || 0;\\n                            const size2 = data2[fullTracebackKey]?.size || 0;\\n                            const diff = size2 - size1;\\n                            if (diff !== 0) {\\n                                const item = data2[fullTracebackKey] || data1[fullTracebackKey];\\n                                diffData.push({ \\n                                    label: item.lastFile,\\n                                    diff: diff,\\n                                    traceback: item.traceback,\\n                                    fullTracebackKey: fullTracebackKey\\n                                });\\n                            }\\n                        });\\n\\n                        currentBreakdownData = diffData.sort((a, b) =&gt; b.diff - a.diff);\\n\\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\\n                        breakdownChart.data.datasets = [{\\n                            label: `Difference`,\\n                            data: currentBreakdownData.map(item =&gt; item.diff),\\n                            backgroundColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 0.6)' : 'rgba(255, 99, 132, 0.6)',\\n                            borderColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 1)' : 'rgba(255, 99, 132, 1)',\\n                            borderWidth: 1\\n                        }];\\n                        breakdownChart.options.plugins.title.text = `Memory Difference: ${formatTimestamp(entry2.start)} vs ${formatTimestamp(entry1.start)}`;\\n\\n                    } else {\\n                        currentBreakdownData = [];\\n                        breakdownChart.data.labels = [];\\n                        breakdownChart.data.datasets = [];\\n                        breakdownChart.options.plugins.title.text = 'Memory Breakdown';\\n                        document.getElementById('tracebackPanel').innerHTML = \\n                            '<div class=\\"no-selection\\">Click a point on the top chart, then a bar below to see details.</div>';\\n                    }\\n                    \\n                    updateChartHeight(breakdownChart, currentBreakdownData.length);\\n                    breakdownChart.update();\\n                    totalChart.update();\\n                };\\n\\n                // --- CHART INSTANTIATION ---\\n                const totalChart = new Chart(document.getElementById('totalMemoryChart'), {\\n                    type: 'line',\\n                    data: {\\n                        labels: lineLabels,\\n                        datasets: [{\\n                            label: 'Total Memory Usage',\\n                            data: totalSizes,\\n                            fill: false,\\n                            borderColor: 'rgba(75, 192, 192, 1)',\\n                            tension: 0.1,\\n                            pointBackgroundColor: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 'rgba(255, 99, 132, 1)' : 'rgba(75, 192, 192, 1)',\\n                            pointRadius: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 7 : 4,\\n                            pointBorderWidth: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 3 : 1\\n                        }]\\n                    },\\n                    options: {\\n                        responsive: true,\\n                        maintainAspectRatio: false,\\n                        plugins: {\\n                            title: { display: true, text: 'Total Memory Usage Over Time (Click to select, Shift+Click to compare)' },\\n                            tooltip: { callbacks: { label: context =&gt; `Total: ${formatBytes(context.raw)}` } }\\n                        },\\n                        onClick: (evt, elements) =&gt; {\\n                            if (elements.length &gt; 0) {\\n                                const idx = elements[0].index;\\n                                const isSelected = selectedIndexes.includes(idx);\\n                                if (evt.native.shiftKey) {\\n                                    if (isSelected) {\\n                                        selectedIndexes = selectedIndexes.filter(i =&gt; i !== idx);\\n                                    } else {\\n                                        selectedIndexes.push(idx);\\n                                        if (selectedIndexes.length &gt; 2) selectedIndexes.shift();\\n                                    }\\n                                } else {\\n                                    selectedIndexes = isSelected &amp;&amp; selectedIndexes.length === 1 ? [] : [idx];\\n                                }\\n                            } else {\\n                                selectedIndexes = [];\\n                            }\\n                            updateBarChart();\\n                        },\\n                        scales: {\\n                            y: { beginAtZero: true, ticks: { callback: formatBytes }, title: { display: true, text: 'Total Memory' } },\\n                            x: { title: { display: true, text: 'Time' } }\\n                        }\\n                    }\\n                });\\n\\n                const breakdownChart = new Chart(document.getElementById('memoryChart'), {\\n                    type: 'bar',\\n                    data: { labels: [], datasets: [] },\\n                    options: {\\n                        indexAxis: 'y',\\n                        responsive: true,\\n                        maintainAspectRatio: false,\\n                        layout: { padding: { right: 120 } },\\n                        plugins: {\\n                            legend: { display: false },\\n                            title: { display: true, text: 'Memory Breakdown' },\\n                            tooltip: { callbacks: { label: context =&gt; `${formatBytes(context.raw)}` } },\\n                            datalabels: {\\n                                anchor: 'end',\\n                                align: 'right',\\n                                color: '#000',\\n                                font: { weight: 'bold', size: 11 },\\n                                formatter: (value) =&gt; formatBytes(value),\\n                                display: true,\\n                                clip: false\\n                            }\\n                        },\\n                        onClick: (evt, elements) =&gt; {\\n                            if (elements.length &gt; 0 &amp;&amp; currentBreakdownData.length &gt; 0) {\\n                                const item = currentBreakdownData[elements[0].index];\\n                                const fullKey = item.fullTracebackKey || getFullTracebackKey(item.traceback);\\n                                showTraceback(item.traceback, Math.abs(item.diff || item.size), fullKey);\\n                            }\\n                        },\\n                        scales: {\\n                            x: { beginAtZero: false, ticks: { callback: formatBytes }, title: { display: true, text: 'Memory Usage / Difference' } },\\n                            y: { title: { display: true, text: 'File:Line' }, ticks: { maxRotation: 0, font: { size: 11 } } }\\n                        }\\n                    },\\n                    plugins: [ChartDataLabels]\\n                });\\n\\n                // Initial render\\n                updateBarChart();\\n            </script>\\n        </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.view_memory">\n        &lt;!DOCTYPE html&gt;\n        <html lang="en">\n        <head>\n            <meta charset="UTF-8"/>\n            <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n            <title>Memory Usage Visualization</title>\n            <script src="https://cdn.jsdelivr.net/npm/chart.js"/>\n            <script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels"/>\n            <style>\n                /* General body and layout styles */\n                body {\n                    font-family: Arial, sans-serif;\n                    margin: 20px;\n                    background-color: #f9f9f9;\n                }\n                .container {\n                    display: flex;\n                    flex-direction: column;\n                    gap: 20px;\n                }\n\n                /* Row definitions for the new layout */\n                .top-row {\n                    height: 40vh; /* Line graph takes 40% of the viewport height */\n                }\n                .bottom-row {\n                    display: flex;\n                    gap: 20px;\n                    /* The height of this row will be determined by its content */\n                }\n\n                /* Chart container styles */\n                .chart-container {\n                    position: relative;\n                    background: #fff;\n                    border: 1px solid #ddd;\n                    border-radius: 5px;\n                    padding: 15px;\n                    height: 100%;\n                    width: 100%;\n                }\n                \n                /* Specific styling for the bottom row elements */\n                .bar-chart-wrapper {\n                    flex: 2; /* Bar chart takes 2/3 of the width */\n                    min-height: 400px; /* Minimum height for the bar chart */\n                }\n                .traceback-panel {\n                    flex: 1; /* Traceback panel takes 1/3 of the width */\n                    background: #f5f5f5;\n                    border: 1px solid #ddd;\n                    border-radius: 5px;\n                    padding: 15px;\n                    overflow-y: auto;\n                    min-height: 400px; /* Match min-height for alignment */\n                    height: fit-content; /* Adjust height to content */\n                }\n\n                /* Traceback panel content styling */\n                .traceback-header {\n                    font-weight: bold;\n                    margin-bottom: 10px;\n                    color: #333;\n                }\n                .traceback-item {\n                    background: white;\n                    margin: 5px 0;\n                    padding: 8px;\n                    border-radius: 3px;\n                    border-left: 3px solid #007acc;\n                    font-family: monospace;\n                    font-size: 12px;\n                }\n                .traceback-file {\n                    color: #007acc;\n                    font-weight: bold;\n                }\n                .copyable {\n                    cursor: pointer;\n                    user-select: all;\n                    padding: 2px 4px;\n                    border-radius: 3px;\n                    transition: background-color 0.2s;\n                }\n                .copyable:hover {\n                    background-color: #e8f4f8;\n                }\n                .traceback-line {\n                    color: #666;\n                }\n                .no-selection {\n                    color: #999;\n                    font-style: italic;\n                    text-align: center;\n                    padding-top: 50px;\n                }\n            </style>\n        </head>\n        <body>\n            <div class="container">\n                <!-- Top row for the full-width line chart -->\n                <div class="top-row">\n                    <div class="chart-container">\n                        <canvas id="totalMemoryChart"/>\n                    </div>\n                </div>\n                <!-- Bottom row for the bar chart and traceback panel -->\n                <div class="bottom-row">\n                    <div class="bar-chart-wrapper chart-container" id="memoryChartContainer">\n                        <canvas id="memoryChart"/>\n                    </div>\n                    <div class="traceback-panel" id="tracebackPanel">\n                        <div class="no-selection">Click a point on the top chart, then a bar below to see details.</div>\n                    </div>\n                </div>\n            </div>\n\n            <script>\n                // Get data from Odoo template\n                const rawData = JSON.parse(atob('<t t-esc="memory_graph"/>'));\n\n                // --- UTILITY FUNCTIONS ---\n                function formatBytes(bytes) {\n                    if (bytes === 0) return '0 B';\n                    const k = 1024;\n                    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\n                    const i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));\n                    const value = bytes / Math.pow(k, i);\n                    return `${value.toFixed(1)} ${sizes[i]}`;\n                }\n\n                function formatTimestamp(timestamp) {\n                    const date = new Date(timestamp * 1000);\n                    return date.toLocaleString();\n                }\n\n                function getLastFileFromTraceback(traceback) {\n                    if (!traceback || traceback.length === 0) return "unknown:0";\n                    const lastFrame = traceback[traceback.length - 1];\n                    return `${lastFrame[0]}:${lastFrame[1]}`;\n                }\n                \n                function getFullTracebackKey(traceback) {\n                    if (!traceback || traceback.length === 0) return "unknown";\n                    return traceback.map(frame =&gt; `${frame[0]}:${frame[1]}`).join(' -&gt; ');\n                }\n\n                // --- DYNAMIC UI UPDATES ---\n                function updateChartHeight(chart, dataLength) {\n                    const container = document.getElementById('memoryChartContainer');\n                    if (dataLength === 0) {\n                        container.style.height = '400px'; // Reset to min-height\n                        chart.resize();\n                        return;\n                    }\n                    \n                    const minBarHeight = 35; // Minimum height per bar for readability\n                    const padding = 100; // Extra space for axes and labels\n                    const newHeight = Math.max(400, (dataLength * minBarHeight) + padding);\n                    \n                    container.style.height = newHeight + 'px';\n                    chart.resize();\n                }\n\n                function showTraceback(traceback, size, fullTracebackKey) {\n                    const panel = document.getElementById('tracebackPanel');\n                    if (!traceback || traceback.length === 0) {\n                        panel.innerHTML = '<div class="no-selection">No traceback available</div>';\n                        return;\n                    }\n\n                    let html = `<div class="traceback-header">Traceback (${formatBytes(size)})</div>`;\n\n                    if (fullTracebackKey) {\n                        html += `\n                            <div style="margin-bottom: 10px; padding: 8px; background: #e8f4f8; border-radius: 3px; font-size: 11px; color: #555;">\n                                <strong>Full Path:</strong> <span class="copyable" title="Click to select for copying">${fullTracebackKey}</span>\n                            </div>\n                        `;\n                    }\n\n                    traceback.forEach(frame =&gt; {\n                        const [filename, lineNo, functionName, code] = frame;\n                        html += `\n                            <div class="traceback-item">\n                                <div class="traceback-file copyable" title="Click to select for copying">${filename}:${lineNo}</div>\n                                <div>in <strong>${functionName || 'unknown'}</strong></div>\n                                ${code ? `<div class="traceback-line">${code}</div>` : ''}\n                            </div>\n                        `;\n                    });\n\n                    panel.innerHTML = html;\n                }\n\n                // --- CHART LOGIC ---\n                const totalSizes = rawData.map(entry =&gt;\n                    entry.samples.reduce((sum, sample) =&gt; sum + sample.size, 0)\n                );\n                const lineLabels = rawData.map(entry =&gt; formatTimestamp(entry.start));\n\n                let selectedIndexes = [];\n                let currentBreakdownData = [];\n\n                const updateBarChart = () =&gt; {\n                    if (selectedIndexes.length === 1) {\n                        const entry = rawData[selectedIndexes[0]];\n                        const groupedData = {};\n                        entry.samples.forEach(sample =&gt; {\n                            const key = getLastFileFromTraceback(sample.traceback);\n                            if (!groupedData[key]) {\n                                groupedData[key] = { size: 0, traceback: sample.traceback, samples: [] };\n                            }\n                            groupedData[key].size += sample.size;\n                            groupedData[key].samples.push(sample);\n                        });\n\n                        currentBreakdownData = Object.entries(groupedData).map(([key, data]) =&gt; ({\n                            label: key,\n                            size: data.size,\n                            traceback: data.traceback,\n                            samples: data.samples\n                        })).sort((a, b) =&gt; b.size - a.size);\n\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\n                        breakdownChart.data.datasets = [{\n                            label: `Memory Usage`,\n                            data: currentBreakdownData.map(item =&gt; item.size),\n                            backgroundColor: 'rgba(54, 162, 235, 0.6)',\n                            borderColor: 'rgba(54, 162, 235, 1)',\n                            borderWidth: 1\n                        }];\n                        breakdownChart.options.plugins.title.text = `Memory Breakdown for ${formatTimestamp(entry.start)}`;\n\n                    } else if (selectedIndexes.length === 2) {\n                        const [idx1, idx2] = selectedIndexes.sort((a, b) =&gt; a - b);\n                        const entry1 = rawData[idx1];\n                        const entry2 = rawData[idx2];\n\n                        const groupDataByFullTraceback = (entry) =&gt; {\n                            const grouped = {};\n                            entry.samples.forEach(sample =&gt; {\n                                const key = getFullTracebackKey(sample.traceback);\n                                if (!grouped[key]) {\n                                    grouped[key] = { size: 0, traceback: sample.traceback, lastFile: getLastFileFromTraceback(sample.traceback) };\n                                }\n                                grouped[key].size += sample.size;\n                            });\n                            return grouped;\n                        };\n\n                        const data1 = groupDataByFullTraceback(entry1);\n                        const data2 = groupDataByFullTraceback(entry2);\n                        const labelSet = new Set([...Object.keys(data1), ...Object.keys(data2)]);\n                        \n                        let diffData = [];\n                        labelSet.forEach(fullTracebackKey =&gt; {\n                            const size1 = data1[fullTracebackKey]?.size || 0;\n                            const size2 = data2[fullTracebackKey]?.size || 0;\n                            const diff = size2 - size1;\n                            if (diff !== 0) {\n                                const item = data2[fullTracebackKey] || data1[fullTracebackKey];\n                                diffData.push({ \n                                    label: item.lastFile,\n                                    diff: diff,\n                                    traceback: item.traceback,\n                                    fullTracebackKey: fullTracebackKey\n                                });\n                            }\n                        });\n\n                        currentBreakdownData = diffData.sort((a, b) =&gt; b.diff - a.diff);\n\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\n                        breakdownChart.data.datasets = [{\n                            label: `Difference`,\n                            data: currentBreakdownData.map(item =&gt; item.diff),\n                            backgroundColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 0.6)' : 'rgba(255, 99, 132, 0.6)',\n                            borderColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 1)' : 'rgba(255, 99, 132, 1)',\n                            borderWidth: 1\n                        }];\n                        breakdownChart.options.plugins.title.text = `Memory Difference: ${formatTimestamp(entry2.start)} vs ${formatTimestamp(entry1.start)}`;\n\n                    } else {\n                        currentBreakdownData = [];\n                        breakdownChart.data.labels = [];\n                        breakdownChart.data.datasets = [];\n                        breakdownChart.options.plugins.title.text = 'Memory Breakdown';\n                        document.getElementById('tracebackPanel').innerHTML = \n                            '<div class="no-selection">Click a point on the top chart, then a bar below to see details.</div>';\n                    }\n                    \n                    updateChartHeight(breakdownChart, currentBreakdownData.length);\n                    breakdownChart.update();\n                    totalChart.update();\n                };\n\n                // --- CHART INSTANTIATION ---\n                const totalChart = new Chart(document.getElementById('totalMemoryChart'), {\n                    type: 'line',\n                    data: {\n                        labels: lineLabels,\n                        datasets: [{\n                            label: 'Total Memory Usage',\n                            data: totalSizes,\n                            fill: false,\n                            borderColor: 'rgba(75, 192, 192, 1)',\n                            tension: 0.1,\n                            pointBackgroundColor: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 'rgba(255, 99, 132, 1)' : 'rgba(75, 192, 192, 1)',\n                            pointRadius: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 7 : 4,\n                            pointBorderWidth: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 3 : 1\n                        }]\n                    },\n                    options: {\n                        responsive: true,\n                        maintainAspectRatio: false,\n                        plugins: {\n                            title: { display: true, text: 'Total Memory Usage Over Time (Click to select, Shift+Click to compare)' },\n                            tooltip: { callbacks: { label: context =&gt; `Total: ${formatBytes(context.raw)}` } }\n                        },\n                        onClick: (evt, elements) =&gt; {\n                            if (elements.length &gt; 0) {\n                                const idx = elements[0].index;\n                                const isSelected = selectedIndexes.includes(idx);\n                                if (evt.native.shiftKey) {\n                                    if (isSelected) {\n                                        selectedIndexes = selectedIndexes.filter(i =&gt; i !== idx);\n                                    } else {\n                                        selectedIndexes.push(idx);\n                                        if (selectedIndexes.length &gt; 2) selectedIndexes.shift();\n                                    }\n                                } else {\n                                    selectedIndexes = isSelected &amp;&amp; selectedIndexes.length === 1 ? [] : [idx];\n                                }\n                            } else {\n                                selectedIndexes = [];\n                            }\n                            updateBarChart();\n                        },\n                        scales: {\n                            y: { beginAtZero: true, ticks: { callback: formatBytes }, title: { display: true, text: 'Total Memory' } },\n                            x: { title: { display: true, text: 'Time' } }\n                        }\n                    }\n                });\n\n                const breakdownChart = new Chart(document.getElementById('memoryChart'), {\n                    type: 'bar',\n                    data: { labels: [], datasets: [] },\n                    options: {\n                        indexAxis: 'y',\n                        responsive: true,\n                        maintainAspectRatio: false,\n                        layout: { padding: { right: 120 } },\n                        plugins: {\n                            legend: { display: false },\n                            title: { display: true, text: 'Memory Breakdown' },\n                            tooltip