ible="product_variant_count &lt; 2" placeholder="All variants"/>\n                            <field name="compute_price" string="Price Type" widget="radio" options="{'horizontal': true}" invisible="display_applied_on == '1_product' and compute_price == 'fixed_price'" groups="product.group_product_pricelist"/>\n                            <label for="fixed_price" invisible="compute_price != 'fixed'"/>\n                            <div class="o_row" invisible="compute_price != 'fixed'" style="width: 60% !important;">\n                                <field name="fixed_price" widget="monetary" options="{'currency_field': 'currency_id', 'field_digits': True}"/>\n                                <span class="d-flex gap-2 p-0" invisible="not product_uom_name">per<field name="product_uom_name"/></span>\n                            </div>\n                            <label for="percent_price" string="Discount" invisible="compute_price != 'percentage'"/>\n                            <div class="o_row gap-3" invisible="compute_price != 'percentage'">\n                                <field name="percent_price"/>\n                                <span>%</span>\n                                <t groups="product.group_product_pricelist">\n                                    <span>on</span>\n                                    <field name="base_pricelist_id" placeholder="sales price" domain="[('id', '!=', pricelist_id)]"/>\n                                </t>\n                            </div>\n                        </group>\n                        <group name="pricelist_rule_limits">\n                            <field name="min_quantity" string="Min Qty"/>\n                            <field name="date_start" string="Validity Period" widget="daterange" options="{'end_date_field': 'date_end'}"/>\n                            <field name="date_end" invisible="1"/>\n                        </group>\n                    </group>\n                    <group name="pricelist_rul