               <div class=\\"alert alert-warning mb-2\\" role=\\"alert\\" invisible=\\"not duplicate_payment_ids or state!='draft'\\">\\n                        <span>This payment has the same partner, amount and date as </span>\\n                        <field name=\\"duplicate_payment_ids\\" widget=\\"x2many_buttons\\" string=\\"Duplicated Payments\\"/>\\n                    </div>\\n                    <sheet>\\n                        <!-- Invisible fields -->\\n                        <field name=\\"id\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"need_cancel_request\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_reconciled\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_matched\\" invisible=\\"1\\"/>\\n                        <field name=\\"payment_method_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_partner_bank_account\\" invisible=\\"1\\"/>\\n                        <field name=\\"require_partner_bank_account\\" invisible=\\"1\\"/>\\n                        <field name=\\"available_payment_method_line_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"available_partner_bank_ids\\" invisible=\\"1\\"/>\\n                        <!-- <field name=\\"suitable_journal_ids\\" invisible=\\"1\\"/> -->\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"partner_type\\" invisible=\\"1\\"/>\\n                        <field name=\\"reconciled_invoices_type\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"paired_internal_transfer_payment_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"available_journal_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                            <!-- Invoice stat button -->\\n                            <button name=\\"button_open_invoices\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" invisible=\\"reconciled_invoices_count == 0\\">\\n                                <div class=\\"o_form_field o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">\\n                                        <field name=\\"reconciled_invoices_count\\"/>\\n                                        <span invisible=\\"reconciled_invoices_type != 'invoice'\\"> Invoice</span>\\n                                        <span invisible=\\"reconciled_invoices_type == 'invoice'\\"> Credit Note</span>\\n                                    </span>\\n                                </div>\\n                            </button>\\n\\n                            <!-- Bill stat button -->\\n                            <button name=\\"button_open_bills\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" invisible=\\"reconciled_bills_count == 0\\">\\n                                <div class=\\"o_form_field o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">\\n                                        <field name=\\"reconciled_bills_count\\"/>\\n                                        <span> Bill</span>\\n                                    </span>\\n                                </div>\\n                            </button>\\n\\n                            <!-- Statement stat button -->\\n                            <button name=\\"button_open_statement_lines\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" invisible=\\"reconciled_statement_lines_count == 0\\">\\n                                <div class=\\"o_form_field o_stat_info\\">\\n                                    <field name=\\"reconciled_statement_lines_count\\"/>\\n                                    <span class=\\"o_stat_text\\">Transaction</span>\\n                                </div>\\n                            </button>\\n\\n                            <!-- Journal Entry  button -->\\n                            <button name=\\"button_open_journal_entry\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" invisible=\\"not move_id\\" groups=\\"account.group_account_user,account.group_account_readonly\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Journal Entry</span>\\n                                </div>\\n                            </button>\\n                        </div>\\n\\n                        <widget name=\\"web_ribbon\\" text=\\"Invoicing App Legacy\\" bg_color=\\"text-bg-info\\" invisible=\\"state != 'invoicing_legacy'\\" tooltip=\\"This payment has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting.\\"/>\\n\\n                        <div class=\\"oe_title\\">\\n                            <h1 invisible=\\"state != 'draft'\\"><span>Draft</span></h1>\\n                            <h1 invisible=\\"state == 'draft'\\"><field name=\\"name\\" readonly=\\"1\\"/></h1>\\n                        </div>\\n\\n                        <group name=\\"main_group\\">\\n                            <group name=\\"group1\\">\\n                                <field name=\\"payment_type\\" widget=\\"radio\\" options=\\"{'horizontal': True}\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"partner_id\\" context=\\"{'default_is_company': True}\\" string=\\"Customer\\" options=\\"{'no_quick_create': True}\\" invisible=\\"partner_type != 'customer'\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"partner_id\\" context=\\"{'default_is_company': True}\\" string=\\"Vendor\\" options=\\"{'no_quick_create': True}\\" invisible=\\"partner_type != 'supplier'\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"amount\\"/>\\n                                <div name=\\"amount_div\\" class=\\"o_row\\">\\n                                    <field name=\\"amount\\" readonly=\\"state != 'draft'\\"/>\\n                                    <field name=\\"currency_id\\" options=\\"{'no_create': True, 'no_open': True}\\" required=\\"1\\" readonly=\\"state != 'draft'\\" groups=\\"base.group_multi_currency\\"/>\\n                                </div>\\n                                <field name=\\"date\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"memo\\" string=\\"Memo\\"/>\\n                            </group>\\n                            <group name=\\"group2\\">\\n                                <field name=\\"journal_id\\" domain=\\"[('id', 'in', available_journal_ids)]\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"payment_method_line_id\\" context=\\"{'hide_payment_journal_id': 1}\\" options=\\"{'no_create': True, 'no_open': True}\\" required=\\"1\\" readonly=\\"state != 'draft'\\"/>\\n\\n                                <field name=\\"partner_bank_id\\" string=\\"Customer Bank Account\\" context=\\"{'default_partner_id': partner_id, 'display_account_trust': True}\\" invisible=\\"not show_partner_bank_account or partner_type != 'customer' or payment_type == 'inbound'\\" required=\\"require_partner_bank_account\\"/>\\n\\n                                <field name=\\"partner_bank_id\\" string=\\"Vendor Bank Account\\" context=\\"{'default_partner_id': partner_id, 'display_account_trust': True}\\" invisible=\\"not show_partner_bank_account or partner_type != 'supplier' or payment_type == 'inbound'\\" required=\\"require_partner_bank_account\\"/>\\n\\n                                <!-- This field should always be readonly but using readonly=\\"1\\" overrides the other partner_bank_id\\n                                fields readonly condition in the framework, preventing the modification of these fields -->\\n                                <field name=\\"partner_bank_id\\" string=\\"Company Bank Account\\" context=\\"{'default_partner_id': partner_id, 'display_account_trust': True}\\" invisible=\\"not show_partner_bank_account or payment_type == 'outbound'\\" required=\\"require_partner_bank_account\\"/>\\n                            </group>\\n                            <group>\\n                                <field name=\\"qr_code\\" invisible=\\"1\\"/>\\n                                <div invisible=\\"not qr_code\\" colspan=\\"2\\" class=\\"text-center\\">\\n                                    <field name=\\"qr_code\\" widget=\\"html\\"/>\\n                                </div>\\n                            </group>\\n                        </group>\\n                        <group>\\n                            <!-- To be used in localizations requiring to add a page -->\\n                            <notebook name=\\"payment_notebook\\" colspan=\\"2\\"/>\\n                        </group>\\n                    </sheet>\\n                    <div class=\\"o_attachment_preview\\"/>\\n                    <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Pay">\n                    <header>\n                        <button name="action_post" string="Confirm" type="object" class="oe_highlight" invisible="state != 'draft'" data-hotkey="q"/>\n                        <button name="action_validate" string="Validate" type="object" class="oe_highlight" invisible="state != 'in_process' or move_id" data-hotkey="q"/>\n                        <button name="action_reject" string="Reject" type="object" invisible="state != 'in_process' or not is_sent" data-hotkey="q"/>\n                        <button name="action_draft" string="Reset to Draft" type="object" class="btn btn-secondary" invisible="state in ('draft')" groups="account.group_account_invoice" data-hotkey="w"/>\n                        <button string="Request Cancel" name="button_request_cancel" type="object" groups="account.group_account_invoice" invisible="state != 'in_process' or not move_id or not need_cancel_request" data-hotkey="w"/>\n                        <button name="mark_as_sent" string="Mark as Sent" type="object" data-hotkey="v" invisible="state != 'in_process' or is_sent or payment_method_code != 'manual'"/>\n                        <button name="unmark_as_sent" string="Unmark as Sent" type="object" data-hotkey="k" invisible="state != 'in_process' or not is_sent or payment_method_code != 'manual'"/>\n                        <button name="action_cancel" string="Cancel" type="object" invisible="not id or not (state == 'draft' or (state == 'in_process' and is_sent))" data-hotkey="x"/>\n                        <field name="state" widget="statusbar" statusbar_visible="draft,in_process,paid"/>\n                    </header>\n                    <div class="alert alert-warning mb-2" role="alert" invisible="not duplicate_payment_ids or state!='draft'">\n                        <span>This payment has the same partner, amount and date as </span>\n                        <field name="duplicate_payment_ids" widget="x2many_buttons" string="Duplicated Payments"/>\n                    </div>\n                    <sheet>\n                        <!-- Invisible fields -->\n                        <field name="id" invisible="1"/>\n                        <field name="is_sent" invisible="1"/>\n                        <field name="need_cancel_request" invisible="1"/>\n                        <field name="is_reconciled" invisible="1"/>\n                        <field name="is_matched" invisible="1"/>\n                        <field name="payment_method_code" invisible="1"/>\n                        <field name="show_partner_bank_account" invisible="1"/>\n                        <field name="require_partner_bank_account" invisible="1"/>\n                        <field name="available_payment_method_line_ids" invisible="1"/>\n                        <field name="available_partner_bank_ids" invisible="1"/>\n                        <!-- <field name="suitable_journal_ids" invisible="1"/> -->\n                        <field name="country_code" invisible="1"/>\n                        <field name="partner_type" invisible="1"/>\n                        <field name="reconciled_invoices_type" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="paired_internal_transfer_payment_id" invisible="1"/>\n                        <field name="available_journal_ids" invisible="1"/>\n                        <field name="currency_id" invisible="1"/>\n\n                        <div class="oe_button_box" name="button_box">\n                            <!-- Invoice stat button -->\n                            <button name="button_open_invoices" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_invoices_count == 0">\n                                <div class="o_form_field o_stat_info">\n                                    <span class="o_stat_text">\n                                        <field name="reconciled_invoices_count"/>\n                                        <span invisible="reconciled_invoices_type != 'invoice'"> Invoice</span>\n                                        <span invisible="reconciled_invoices_type == 'invoice'"> Credit Note</span>\n                                    </span>\n                                </div>\n                            </button>\n\n                            <!-- Bill stat button -->\n                            <button name="button_open_bills" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_bills_count == 0">\n                                <div class="o_form_field o_stat_info">\n                                    <span class="o_stat_text">\n                                        <field name="reconciled_bills_count"/>\n                                        <span> Bill</span>\n                                    </span>\n                                </div>\n                            </button>\n\n                            <!-- Statement stat button -->\n                            <button name="button_open_statement_lines" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_statement_lines_count == 0">\n                                <div class="o_form_field o_stat_info">\n                                    <field name="reconciled_statement_lines_count"/>\n                                    <span class="o_stat_text">Transaction</span>\n                                </div>\n                            </button>\n\n                            <!-- Journal Entry  button -->\n                            <button name="button_open_journal_entry" type="object" class="oe_stat_button" icon="fa-bars" invisible="not move_id" groups="account.group_account_user,account.group_account_readonly">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Journal Entry</span>\n                                </div>\n                            </button>\n                        </div>\n\n                        <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="state != 'invoicing_legacy'" tooltip="This payment has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting."/>\n\n                        <div class="oe_title">\n                            <h1 invisible="state != 'draft'"><span>Draft</span></h1>\n                            <h1 invisible="state == 'draft'"><field name="name" readonly="1"/></h1>\n                        </div>\n\n                        <group name="main_group">\n                            <group name="group1">\n                                <field name="payment_type" widget="radio" options="{'horizontal': True}" readonly="state != 'draft'"/>\n                                <field name="partner_id" context="{'default_is_company': True}" string="Customer" options="{'no_quick_create': True}" invisible="partner_type != 'customer'" readonly="state != 'draft'"/>\n                                <field name="partner_id" context="{'default_is_company': True}" string="Vendor" options="{'no_quick_create': True}" invisible="partner_type != 'supplier'" readonly="state != 'draft'"/>\n                                <label for="amount"/>\n                                <div name="amount_div" class="o_row">\n                                    <field name="amount" readonly="state != 'draft'"/>\n                                    <field name="currency_id" options="{'no_create': True, 'no_open': True}" required="1" readonly="state != 'draft'" groups="base.group_multi_currency"/>\n                                </div>\n                                <field name="date" readonly="state != 'draft'"/>\n                                <field name="memo" string="Memo"/>\n                            </group>\n                            <group name="group2">\n                                <field name="journal_id" domain="[('id', 'in', available_journal_ids)]" readonly="state != 'draft'"/>\n                                <field name="payment_method_line_id" context="{'hide_payment_journal_id': 1}" options="{'no_create': True, 'no_open': True}" required="1" readonly="state != 'draft'"/>\n\n                                <field name="partner_bank_id" string="Customer Bank Account" context="{'default_partner_id': partner_id, 'display_account_trust': True}" invisible="not show_partner_bank_account or partner_type != 'customer' or payme