  </setting>\n                        </block>\n                        <block title="Taxes" name="default_taxes_setting_container">\n                            <setting id="default_taxes" string="Default Taxes" company_dependent="1" help="Default taxes applied when creating new products." documentation="/applications/finance/accounting/taxation/taxes/default_taxes.html">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label string="Sales Tax" for="sale_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="sale_tax_id" domain="[('type_tax_use', 'in', ('sale', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Purchase Tax" for="purchase_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="purchase_tax_id" domain="[('type_tax_use', 'in', ('purchase', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <div class="col-lg-3">\n                                            <label string="Prices" for="account_price_include" class="o_light_label"/>\n                                            <div class="fa fa-question-circle" title="This setting locks once a journal entry is created."/>\n                                        </div>\n                                        <field name="account_price_include" readonly="has_accounting_entries"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="rounding_method" company_dependent="1" string="Rounding Method" help="How total tax amount is computed in orders and invoices" title="A rounding per line is advised if your prices are tax-included. That way, the sum of line subtotals equals the total with taxes.">\n                                <field name="tax_calculation_rounding_method" class="o_light_label mt16" widget="radio"/>\n                            </setting>\n                            <setting id="eu_service" title="If you sell goods and services to customers in a                                 foreign EU country, you must charge VAT based on the delivery address.                                 This rule applies regardless of where you are located." string="EU Intra-community Distance Selling" documentation="/applications/finance/accounting/taxation/taxes/eu_distance_selling.html" help="Apply VAT of the EU country to which goods and services are delivered." invisible="not('EU' in company_country_group_codes or company_country_code in ('CH', 'UK'))">\n                                <button type="object" name="action_eu_oss_tax_mapping" icon="fa-refresh" string="OSS Tax mapping" class="btn-link"/>\n                            </setting>\n                            <setting id="tax_exigibility" company_dependent="1" help="Allow to configure taxes using cash basis" title="Select this if the taxes should use cash basis, which will create an entry for such taxes on a given account during reconciliation." documentation="/applications/finance/accounting/taxation/taxes/cash_basis_taxes.html">\n                                <field name="tax_exigibility"/>\n                                <div class="content-group" invisible="not tax_exigibility" groups="account.group_account_user">\n                                    <div class="row mt16">\n                                        <label for="tax_cash_basis_journal_id" class="col-lg-3 o_light_label"/>\n                                        <field name="tax_cash_basis_journal_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                        