ps="sales_team.group_sale_salesman" type="object" name="action_redirect_to_quotations" class="btn-outline-primary rounded-pill me-1 order-2">\n                    <span class="badge">\n                        <i class="fa fa-fw fa-money me-1" aria-label="Quotations" role="img"/>\n                        <field name="quotation_count"/>\n                    </span>\n                </a>\n            </xpath>\n        	f	t	2026-06-04 08:49:17.305712	2026-06-04 08:49:17.305712	f
